// Hand-written. Not generated by Speakeasy.
//
// Guards the trust anchor key sets against private material.
//
// A trust anchor is an entity this service verifies signatures from, never one
// it signs as, so its JWK Set is public by definition and the specification
// says so. A private key there is always a mistake, and an expensive one:
// Terraform stores a string attribute in state whole, so the key sits in the
// state file for an entity that has no use for it, and nothing reports it.
//
// Plan time is the only point at which the practitioner can still act on it,
// which is why this is an attribute validator rather than anything in the
// apply path. The same reasoning already applies to a client's jwks; this
// extends it to the one remaining key set that is public by contract.
//
// The wiring lives in .speakeasy/terraform_overlay.yaml. These tests exist
// because an overlay edit or a generator change could drop it silently: the
// provider would still build, and a configuration carrying a private key would
// still apply.
package provider

import (
	"context"
	"strings"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/schema/validator"
	"github.com/hashicorp/terraform-plugin-framework/types"

	"github.com/authlete/terraform-provider-authlete/v3/internal/provider/customtypes"
)

// trustAnchorJwks digs the nested attribute out of the service schema.
func trustAnchorJwks(t *testing.T) schema.StringAttribute {
	t.Helper()

	attr, ok := resourceSchema(t, NewServiceResource()).Attributes["trust_anchors"]
	if !ok {
		t.Fatal("authlete_service has no trust_anchors attribute")
	}
	nested, ok := attr.(schema.ListNestedAttribute)
	if !ok {
		t.Fatalf("trust_anchors is %T, expected a list of nested objects", attr)
	}
	jwks, ok := nested.NestedObject.Attributes["jwks"]
	if !ok {
		t.Fatal("a trust anchor has no jwks attribute")
	}
	str, ok := jwks.(schema.StringAttribute)
	if !ok {
		t.Fatalf("trust_anchors[].jwks is %T, expected a string attribute", jwks)
	}
	return str
}

// The custom type is what compares two spellings of the same key set by
// meaning. Without it a key set Authlete reformats shows a diff on every plan,
// which is the defect already fixed for the service and client sets.
func TestTrustAnchorKeySetIsComparedByMeaning(t *testing.T) {
	if _, ok := trustAnchorJwks(t).CustomType.(customtypes.PublicJWKSType); !ok {
		t.Errorf("trust_anchors[].jwks has custom type %T, want customtypes.PublicJWKSType.\n\n"+
			"Without it the attribute is compared byte for byte, so a key set "+
			"Authlete reformats plans a change on every run.\n\n"+
			"Restore x-speakeasy-terraform-custom-type on "+
			"$.components.schemas.trust_anchor.properties.jwks in "+
			".speakeasy/terraform_overlay.yaml and regenerate.",
			trustAnchorJwks(t).CustomType)
	}
}

// The validator is what refuses the private key. The custom type alone would
// compare correctly and still accept it.
func TestTrustAnchorKeySetRefusesPrivateKeys(t *testing.T) {
	validators := trustAnchorJwks(t).Validators
	if len(validators) == 0 {
		t.Fatal("trust_anchors[].jwks has no validators.\n\n" +
			"Restore x-speakeasy-plan-validators: [ValidPublicJWKSet] on " +
			"$.components.schemas.trust_anchor.properties.jwks in " +
			".speakeasy/terraform_overlay.yaml and regenerate.")
	}

	for name, tc := range map[string]struct {
		doc      string
		accepted bool
	}{
		"a public RSA key": {
			`{"keys":[{"kty":"RSA","kid":"ta","n":"zyC5","e":"AQAB"}]}`, true,
		},
		"an RSA key carrying its private exponent": {
			`{"keys":[{"kty":"RSA","kid":"ta","n":"zyC5","e":"AQAB","d":"Xk2p"}]}`, false,
		},
		"an EC key carrying its private exponent": {
			`{"keys":[{"kty":"EC","kid":"ta","crv":"P-256","x":"f83O","y":"x_FE","d":"jpsQ"}]}`, false,
		},
		"a symmetric key": {
			`{"keys":[{"kty":"oct","kid":"ta","k":"c3VwZXItc2VjcmV0"}]}`, false,
		},
	} {
		t.Run(name, func(t *testing.T) {
			req := validator.StringRequest{
				Path:        path.Root("trust_anchors").AtListIndex(0).AtName("jwks"),
				ConfigValue: types.StringValue(tc.doc),
			}
			resp := &validator.StringResponse{}
			for _, v := range validators {
				v.ValidateString(context.Background(), req, resp)
			}

			if tc.accepted && resp.Diagnostics.HasError() {
				t.Errorf("a public key set was refused: %v", resp.Diagnostics)
			}
			if !tc.accepted && !resp.Diagnostics.HasError() {
				t.Error("private key material was accepted.\n\n" +
					"It reaches the state file, where it sits in plain text for an " +
					"entity this service only ever verifies signatures from.")
			}
		})
	}
}

// A null or unknown configuration must pass. trust_anchors is computed as well
// as optional, so a practitioner who never mentions it still gets whatever
// Authlete holds read back, and a validator that fired on that would break
// every refresh.
func TestTrustAnchorValidatorIgnoresAbsentConfiguration(t *testing.T) {
	for name, v := range map[string]types.String{
		"null":    types.StringNull(),
		"unknown": types.StringUnknown(),
	} {
		t.Run(name, func(t *testing.T) {
			resp := &validator.StringResponse{}
			for _, val := range trustAnchorJwks(t).Validators {
				val.ValidateString(context.Background(), validator.StringRequest{
					Path:        path.Root("trust_anchors").AtListIndex(0).AtName("jwks"),
					ConfigValue: v,
				}, resp)
			}
			if resp.Diagnostics.HasError() {
				t.Errorf("a %s value was refused: %v", name, resp.Diagnostics)
			}
		})
	}
}

// The error has to name the member that caused it, or a practitioner with a
// large key set cannot tell which key to replace.
func TestTrustAnchorRefusalNamesTheOffendingMember(t *testing.T) {
	resp := &validator.StringResponse{}
	for _, v := range trustAnchorJwks(t).Validators {
		v.ValidateString(context.Background(), validator.StringRequest{
			Path:        path.Root("trust_anchors").AtListIndex(0).AtName("jwks"),
			ConfigValue: types.StringValue(`{"keys":[{"kty":"RSA","kid":"ta","n":"zyC5","e":"AQAB","d":"Xk2p"}]}`),
		}, resp)
	}
	if !resp.Diagnostics.HasError() {
		t.Fatal("precondition: this key set must be refused")
	}
	detail := resp.Diagnostics.Errors()[0].Summary() + " " + resp.Diagnostics.Errors()[0].Detail()
	if !strings.Contains(detail, "d") || !strings.Contains(detail, "ta") {
		t.Errorf("the refusal names neither the private member nor the key id:\n%s", detail)
	}
}
